'use strict';
const $=(selector,root=document)=>root.querySelector(selector);
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={overview:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',applications:'M8 3h8v4H8z M8 5H5v16h14V5h-3 M8 12h8 M8 16h5',dispatches:'M4 5h16v14H4z M4 9h16 M8 2v6 M16 2v6 M8 13h3 M14 13h2',vehicles:'M5 17H3V9l2-5h14l2 5v8h-2 M3 10h18 M7 17h10 M6 17v3 M18 17v3 M6 13h2 M16 13h2',bookings:'M4 5h16v14H4z M4 9h16 M8 2v6 M16 2v6 M8 13h3 M14 13h2',statistics:'M4 20h16 M7 16V10 M12 16V4 M17 16V7'};
const icon=name=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.applications}"/></svg>`;
const statusNames={pending:'待審核',approved:'已核准',rejected:'未核准',cancelled:'已取消',available:'目前可借',maintenance:'保養中',retired:'已停用',dispatched:'使用中',returned:'已歸還',upcoming:'已預約'};
const badge=status=>`<span class="badge ${esc(status)}">${esc(statusNames[status]||status)}</span>`;
const date=value=>value?new Date(value).toLocaleString('zh-TW',{timeZone:'Asia/Taipei',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}):'—';
const views={overview:['我的用車'],applications:['我的申請'],bookings:['車輛預約'],vehicles:['車輛紀錄'],statistics:['個人統計']};
let role='employee',authEpoch=0,devBusy=false,devDraft=null,devFileVersion=0;
let current='overview',employeeId=null,csrfToken=null,context=null,rows=[],formMode=null,requestVersion=0,selectedVehicle=null,historyType='maintenance';
$('#today').textContent=new Date().toLocaleDateString('zh-TW',{timeZone:'Asia/Taipei',year:'numeric',month:'long',day:'numeric'});
async function api(path,method='GET',body){
  const epoch=authEpoch;let response;try{response=await fetch(path,{method,credentials:'same-origin',headers:{'Content-Type':'application/json',...(csrfToken?{'X-CSRF-Token':csrfToken}:{})},...(body===undefined?{}:{body:JSON.stringify(body)}),signal:AbortSignal.timeout(18000)});}catch{setConnection(false);throw new Error(path.startsWith('/api/dev/')&&method!=='GET'?'連線中斷，操作結果未確認。請重新載入並核對紀錄後再操作，避免重複寫入。':'網站暫時無法連線，請稍後再試。');}
  const data=await response.json().catch(()=>({}));if(!response.ok){if(response.status===401&&epoch===authEpoch&&!path.startsWith('/api/auth/')&&!['/api/dev/session','/api/dev/login'].includes(path))showLogin();let detail=data.detail;if(Array.isArray(detail))detail=detail.map(v=>v.msg).join('；');throw new Error(detail||`操作失敗（${response.status}）`);}setConnection(true);return data;
}
function setConnection(connected){$('#connection-state').textContent=connected?'已連線':'連線中斷';$('#connection-state').classList.toggle('offline',!connected);}
function personalPath(resource,record=null,action=null){return `/api/${resource}${record?`/${record}`:''}${action?`/${action}`:''}`;}
function renderNav(){$('#nav').innerHTML=Object.entries(views).map(([key,view])=>`<a href="#${key}" class="nav-item ${current===key?'active':''}" ${current===key?'aria-current="page"':''}>${icon(key)}${view[0]}</a>`).join('');}
function empty(title='目前沒有紀錄',description=''){return `<div class="empty">${icon(current)}<strong>${esc(title)}</strong>${description?`<p>${esc(description)}</p>`:''}</div>`;}
function error(message){$('#error-banner').textContent=message;$('#error-banner').hidden=false;}
function toast(message){$('#toast').textContent=message;$('#toast').hidden=false;setTimeout(()=>{$('#toast').hidden=true;},4000);}
function tripStatus(trip){return trip.returned_at?'returned':new Date(trip.actual_start_date)>new Date()?'upcoming':'dispatched';}
function canChange(request){return !request.dispatch_id||(!request.returned_at&&new Date(request.dispatch_start_date||request.requested_start_date)>new Date());}
function canEdit(request){return canChange(request)&&['pending','approved'].includes(request.approval_status);}
function statCards(cards){return `<div class="stats-grid">${cards.map((card,index)=>`<article class="stat-card ${index===1?'accent':''}"><small>${card[0]}</small><strong>${esc(card[1])}</strong></article>`).join('')}</div>`;}
function profile(){const person=context.employee;$('#employee-name').textContent=person.employee_name;$('#employee-department').textContent=person.department_name;$('#employee-avatar').textContent=person.employee_name.slice(0,1);$('#signed-in-name').textContent='員工編號 '+person.employee_id;}
async function loadPage(){
  if(role==='dev')return loadDevPage();
  const version=++requestVersion,owner=employeeId,key=location.hash.slice(1)||'overview';current=key==='dispatches'?'applications':views[key]?key:'overview';renderNav();$('#breadcrumb').textContent=views[current][0];$('#page-title').textContent=views[current][0];
  $('#error-banner').hidden=true;$('#add-button').hidden=current!=='applications';$('#add-button').disabled=true;$('#add-button').textContent='申請用車';
  if(!owner){showLogin();return;}$('#page-content').innerHTML='<div class="loading">正在載入你的用車資料…</div>';
  try{const result=await api(personalPath('employee-context'));if(version!==requestVersion||owner!==employeeId)return;context=result;profile();$('#add-button').disabled=false;if(current==='overview')renderOverview();else if(current==='statistics')renderStatistics();else if(current==='vehicles')renderVehicles();else if(current==='bookings')renderBookings();else{rows=context[current];renderList();}}
  catch(e){if(version!==requestVersion)return;error(e.message);$('#page-content').innerHTML=empty('資料尚未載入','請確認連線後重新整理頁面。');}
}
function renderOverview(){
  const {applications,dispatches}=context,trips=dispatches.filter(t=>!t.returned_at).sort((a,b)=>new Date(a.actual_start_date)-new Date(b.actual_start_date));
  $('#page-content').innerHTML=`${statCards([['我的申請',applications.length],['尚未歸還',trips.length],['已完成',dispatches.filter(t=>t.returned_at).length]])}<section class="panel next-trip"><div class="panel-heading"><h2>下一趟行程</h2><a href="#applications" class="text-link">我的申請 →</a></div>${trips.length?`<ul class="trip-list" aria-label="已預約與使用中的行程">${trips.map(trip=>`<li class="trip-details"><div><h3>${esc(trip.license_plate)}</h3>${badge(tripStatus(trip))}</div><p>${esc(trip.purpose)}</p><dl><dt>出發</dt><dd>${date(trip.actual_start_date)}</dd><dt>歸還</dt><dd>${date(trip.actual_end_date)}</dd></dl></li>`).join('')}</ul>`:empty('目前沒有行程')}</section>`;
}
function requestStatus(request){return request.approval_status==='approved'&&request.dispatch_id?tripStatus({actual_start_date:request.dispatch_start_date,returned_at:request.returned_at}):request.approval_status;}
const columns={applications:[['申請 / 用途',a=>`<strong>${esc(a.purpose)}</strong><span class="sub">#${a.application_id}</span>`],['使用期間',a=>`${date(a.dispatch_start_date||a.requested_start_date)}<span class="sub">至 ${date(a.dispatch_end_date||a.requested_end_date)}</span>`],['狀態',a=>`${badge(requestStatus(a))}${a.returned_at?`<span class="sub">${date(a.returned_at)}</span>`:''}`],['車牌',a=>esc(a.license_plate||'尚未指派')]]};
function actions(row){
  if(row.dispatch_id&&!row.returned_at&&new Date(row.dispatch_start_date)<=new Date())return `<div class="table-actions"><button type="button" data-action="return" data-id="${row.dispatch_id}">登記歸還</button></div>`;
  const button=(label,action,danger=false)=>`<button type="button" data-action="${action}" data-id="${row.application_id}" class="${danger?'danger':''}">${label}</button>`;
  return `<div class="table-actions">${canEdit(row)?button('修改','edit'):''}${canEdit(row)?button('取消','cancel'):''}${canChange(row)?button('刪單','delete',true):'<span class="muted">已完成</span>'}</div>`;
}
function renderList(){
  const filter=`<select id="status-filter" aria-label="申請狀態篩選"><option value="">全部狀態</option>${['pending','approved','upcoming','dispatched','returned','rejected','cancelled'].map(v=>`<option value="${v}">${v==='approved'?'已核准（全部）':statusNames[v]}</option>`).join('')}</select>`;
  $('#page-content').innerHTML=`<section class="panel"><div class="toolbar"><input type="search" id="search" placeholder="搜尋用途、車牌或單號…" aria-label="搜尋我的紀錄">${filter}<span class="record-count" id="record-count"></span></div><div class="table-scroll"><table class="applications-table"><thead><tr>${columns[current].map(c=>`<th>${c[0]}</th>`).join('')}<th>操作</th></tr></thead><tbody id="list-body"></tbody></table></div></section>`;$('#search').addEventListener('input',filterRows);$('#status-filter').addEventListener('change',filterRows);filterRows();
}
function filterRows(){
  const search=$('#search').value.trim().toLowerCase(),status=$('#status-filter').value,filtered=rows.filter(row=>Object.values(row).join(' ').toLowerCase().includes(search)&&(!status||(status==='approved'?row.approval_status:requestStatus(row))===status));$('#record-count').textContent=`${filtered.length} 筆`;
  $('#list-body').innerHTML=filtered.length?filtered.map(row=>`<tr>${columns[current].map(c=>`<td>${c[1](row)}</td>`).join('')}<td>${actions(row)}</td></tr>`).join(''):`<tr><td colspan="${columns[current].length+1}">${empty(search||status?'沒有符合的結果':current==='applications'?'尚無申請':'尚無行程')}</td></tr>`;
}
function vehicleHistory(){
  const vehicle=context.vehicles.find(v=>String(v.vehicle_id)===selectedVehicle);
  if(!vehicle)return '';
  const maintenance=historyType==='maintenance',dateKey=maintenance?'maintenance_date':'refueling_date';
  const records=(context[historyType]||[]).filter(r=>String(r.vehicle_id)===selectedVehicle).sort((a,b)=>String(b[dateKey]).localeCompare(String(a[dateKey])));
  return `<section class="panel vehicle-detail" aria-labelledby="selected-plate"><div class="vehicle-summary"><img src="/cullinan.webp" alt="Rolls-Royce Cullinan" width="180" height="112"><div><h2 id="selected-plate">${esc(vehicle.license_plate)}</h2><p>${esc(vehicle.vehicle_model)}</p></div></div><div class="segmented" role="group" aria-label="紀錄類型"><button type="button" data-history="maintenance" aria-pressed="${maintenance}">保養紀錄</button><button type="button" data-history="refueling" aria-pressed="${!maintenance}">加油紀錄</button></div><div class="table-scroll"><table aria-label="${esc(vehicle.license_plate)}${maintenance?'保養':'加油'}紀錄"><thead><tr><th>日期</th><th>${maintenance?'保養項目':'公升數'}</th><th>金額</th></tr></thead><tbody>${records.length?records.map(r=>`<tr><td>${esc(String(r[dateKey]).slice(0,10))}</td><td>${maintenance?esc(r.maintenance_item):Number(r.fuel_liters).toLocaleString('zh-TW',{maximumFractionDigits:3})+' L'}</td><td>${Number(maintenance?r.maintenance_cost:r.fuel_cost).toLocaleString('zh-TW',{style:'currency',currency:'TWD',maximumFractionDigits:0})}</td></tr>`).join(''):`<tr><td colspan="3">${empty('尚無紀錄')}</td></tr>`}</tbody></table></div></section>`;
}
function renderVehicles(){
  if(!context.vehicles.some(v=>String(v.vehicle_id)===selectedVehicle))selectedVehicle=null;
  $('#page-content').innerHTML=`<div class="vehicle-picker" role="group" aria-label="選擇車輛">${context.vehicles.map(v=>`<button type="button" class="vehicle-choice" data-vehicle="${v.vehicle_id}" aria-pressed="${String(v.vehicle_id)===selectedVehicle}"><span class="vehicle-choice-top">${icon('vehicles')}${badge(v.in_use?'dispatched':v.vehicle_status)}</span><strong>${esc(v.license_plate)}</strong></button>`).join('')}</div><div id="vehicle-history">${vehicleHistory()}</div>`;
  $('.vehicle-picker').addEventListener('click',event=>{const button=event.target.closest('[data-vehicle]');if(!button)return;selectedVehicle=button.dataset.vehicle;historyType='maintenance';$$vehicleSelection();});
  $('#vehicle-history').addEventListener('click',event=>{const button=event.target.closest('[data-history]');if(!button)return;historyType=button.dataset.history;$('#vehicle-history').innerHTML=vehicleHistory();$(`[data-history="${historyType}"]`).focus();});
}
function $$vehicleSelection(){document.querySelectorAll('[data-vehicle]').forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.vehicle===selectedVehicle)));$('#vehicle-history').innerHTML=vehicleHistory();}
let availabilityVersion=0,formAvailabilityVersion=0;
const periodQuery=(start,end)=>`/api/availability?start=${encodeURIComponent(start)}&end=${encodeURIComponent(end)}`;
function bookingsTable(records){return `<div class="table-scroll"><table class="bookings-table"><thead><tr><th>車牌</th><th>員工</th><th>用途</th><th>出發</th><th>歸還</th></tr></thead><tbody>${records.length?records.map(r=>`<tr><td>${esc(r.license_plate)}</td><td>${esc(r.employee_name)}</td><td>${esc(r.purpose)}</td><td>${date(r.actual_start_date)}</td><td>${date(r.actual_end_date)}</td></tr>`).join(''):`<tr><td colspan="5">${empty('尚無預約')}</td></tr>`}</tbody></table></div>`;}
function renderBookings(){const start=localTime(new Date(Date.now()+3600000)),end=localTime(new Date(Date.now()+10800000));$('#page-content').innerHTML=`<section class="panel"><form id="availability-form" class="availability-form"><label for="availability-start">出發<input id="availability-start" type="datetime-local" value="${start}" required></label><label for="availability-end">歸還<input id="availability-end" type="datetime-local" value="${end}" required></label><button class="primary" type="submit">查空車</button></form><div id="availability-result" aria-live="polite"></div></section><section class="panel"><div class="panel-heading"><h2>大家的預約</h2></div>${bookingsTable(context.team_bookings||[])}</section>`;$('#availability-form').addEventListener('submit',event=>{event.preventDefault();checkAvailability();});checkAvailability();}
async function checkAvailability(){const version=++availabilityVersion;$('#availability-result').innerHTML='<div class="loading">查詢中…</div>';try{const data=await api(periodQuery(new Date($('#availability-start').value+':00+08:00').toISOString(),new Date($('#availability-end').value+':00+08:00').toISOString()));if(version!==availabilityVersion||current!=='bookings')return;$('#availability-result').innerHTML=`<div class="employee-vehicle-grid">${data.vehicles.map(v=>`<article class="employee-vehicle-card"><div><strong>${esc(v.license_plate)}</strong><span class="badge ${v.available_in_period?'available':'maintenance'}">${v.available_in_period?'可借':v.vehicle_status==='maintenance'?'保養中':'已預約'}</span></div></article>`).join('')}</div>`;}catch(e){if(version===availabilityVersion&&current==='bookings')$('#availability-result').innerHTML=`<div class="form-error availability-error" role="alert">${esc(e.message)}</div>`;}}
async function refreshFormVehicles(){const version=++formAvailabilityVersion,select=$('#field-vehicle'),owner=employeeId;if(!select)return;const selected=select.value;select.disabled=true;$('#vehicle-hint').textContent='';try{const data=await api(periodQuery(new Date($('#field-start').value+':00+08:00').toISOString(),new Date($('#field-end').value+':00+08:00').toISOString())+(formMode.record?'&exclude='+formMode.record.application_id:''));if(version!==formAvailabilityVersion||owner!==employeeId||!$('#edit-dialog').open)return;select.innerHTML='<option value="">自動安排</option>'+data.vehicles.map(v=>`<option value="${v.vehicle_id}" ${!v.available_in_period?'disabled':''}>${esc(v.license_plate)}${v.available_in_period?'':'（無法借用）'}</option>`).join('');if(data.vehicles.some(v=>String(v.vehicle_id)===selected&&v.available_in_period))select.value=selected;$('#vehicle-hint').textContent=data.vehicles.some(v=>v.available_in_period)?'':'此時段無可借車輛。';}catch(e){if(version===formAvailabilityVersion&&$('#edit-dialog').open)$('#vehicle-hint').textContent=e.message;}finally{if(version===formAvailabilityVersion&&$('#edit-dialog').open)select.disabled=false;}}
// API supplies six chronological, zero-filled months. Keep counts and labels visible
// outside SVG so they remain readable at mobile widths and browser zoom.
function monthlyApplicationsChart(months){
  const max=Math.max(0,...months.map(m=>Number(m.applications)));
  const step=Math.max(1,Math.ceil(max/4)),ceiling=step*4;
  const points=months.map((m,i)=>({month:m.month,count:Number(m.applications),x:(i+.5)/months.length*100,y:(1-Number(m.applications)/ceiling)*100}));
  const summary=points.map(p=>`${p.month}：${p.count} 筆`).join('；');
  return `<figure class="monthly-chart" aria-label="近六個月申請折線圖"><figcaption class="monthly-chart-caption">申請數（筆）${max===0?' · 近六個月尚無申請':''}</figcaption><div class="monthly-chart-visual" role="img" aria-label="${esc(summary)}"><div class="monthly-chart-plot">${Array.from({length:5},(_,i)=>`<div class="monthly-chart-grid" style="top:${i*25}%"><span>${ceiling-i*step}</span></div>`).join('')}<svg class="monthly-chart-line" viewBox="0 0 100 100" preserveAspectRatio="none" aria-hidden="true"><polyline points="${points.map(p=>`${p.x},${p.y}`).join(' ')}"/></svg>${points.map(p=>`<div class="monthly-chart-point" style="left:${p.x}%;top:${p.y}%"><span>${p.count}</span></div>`).join('')}</div><div class="monthly-chart-months">${points.map(p=>`<span>${esc(p.month).replace('-', '<wbr>-')}</span>`).join('')}</div></div></figure>`;
}
function renderStatistics(){
  const data=context.statistics,s=data.totals;$('#page-content').innerHTML=`${statCards([['累計申請',s.applications],['用車次數',s.dispatches],['已歸還',s.returned],['預約時數',s.scheduled_hours+' 小時']])}<section class="panel"><div class="panel-heading"><h2>近六個月申請</h2></div>${monthlyApplicationsChart(data.months)}</section><section class="panel"><div class="panel-heading"><h2>申請狀態</h2></div><div class="status-summary">${data.approval_status.map(v=>`<div>${badge(v.approval_status)}<strong>${v.count}</strong></div>`).join('')||empty('尚無申請')}</div></section>`;
}
function localTime(value){const parts=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Taipei',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(new Date(value)),get=type=>parts.find(p=>p.type===type).value;return `${get('year')}-${get('month')}-${get('day')}T${get('hour')}:${get('minute')}`;}
function openForm(record=null){
  if(!context||!employeeId)return;formMode={owner:employeeId,record};const start=record?.requested_start_date||new Date(Date.now()+3600000).toISOString(),end=record?.requested_end_date||new Date(Date.now()+10800000).toISOString();$('#dialog-title').textContent=record?'修改我的申請':'申請公務用車';$('#form-error').textContent='';$('#save-button').textContent=record?'儲存':'送出申請';
  $('#form-fields').innerHTML=`<label for="field-purpose">借用用途<textarea id="field-purpose" name="purpose" required maxlength="500" >${esc(record?.purpose||'')}</textarea></label><div class="form-date-grid"><label for="field-start">預計出發<input id="field-start" name="requested_start_date" type="datetime-local" value="${localTime(start)}" required></label><label for="field-end">預計歸還<input id="field-end" name="requested_end_date" type="datetime-local" value="${localTime(end)}" required></label></div><label for="field-vehicle">車輛<select id="field-vehicle" name="vehicle_id"><option value="">自動安排</option>${record?.vehicle_id?`<option value="${record.vehicle_id}" selected>${esc(record.license_plate)}</option>`:''}</select></label><p class="field-hint" id="vehicle-hint" role="status"></p>`;$('#edit-dialog').showModal();$('#field-start').addEventListener('change',refreshFormVehicles);$('#field-end').addEventListener('change',refreshFormVehicles);refreshFormVehicles();
}
$('#add-button').addEventListener('click',()=>openForm());$('#close-dialog').addEventListener('click',()=>$('#edit-dialog').close());$('#cancel-dialog').addEventListener('click',()=>$('#edit-dialog').close());
$('#edit-form').addEventListener('submit',async event=>{
  event.preventDefault();if(role==='dev'){await saveDevForm(event.target);return;}$('#save-button').disabled=true;$('#form-error').textContent='';try{const fields=Object.fromEntries(new FormData(event.target)),body={employee_id:formMode.owner,purpose:fields.purpose,requested_start_date:new Date(fields.requested_start_date+':00+08:00').toISOString(),requested_end_date:new Date(fields.requested_end_date+':00+08:00').toISOString(),...(fields.vehicle_id?{vehicle_id:Number(fields.vehicle_id)}:{})};const result=await api(personalPath('my-applications',formMode.record?.application_id,null,formMode.owner),formMode.record?'PUT':'POST',body);$('#edit-dialog').close();toast(`申請已自動核准，車牌：${result.license_plate}`);if(location.hash==='#applications')await loadPage();else location.hash='applications';}catch(e){$('#form-error').textContent=e.message;}finally{$('#save-button').disabled=false;}
});
$('#page-content').addEventListener('click',async event=>{
  const button=event.target.closest('[data-action]');if(!button)return;const action=button.dataset.action,id=Number(button.dataset.id);if(action==='new')return openForm();if(action==='edit')return openForm(context.applications.find(a=>a.application_id===id));const prompt={delete:'刪除申請並釋放預約？無法復原。',cancel:'取消申請並釋放預約？',return:'確認歸還？'}[action];if(!prompt||!confirm(prompt))return;button.disabled=true;
  try{if(action==='delete')await api(personalPath('my-applications',id),'DELETE');else if(action==='cancel')await api(personalPath('my-applications',id,'cancel'),'POST');else await api(personalPath('my-dispatches',id,'return'),'POST');toast(action==='delete'?'申請已刪除，車輛預約已釋放':action==='cancel'?'申請已取消':'已完成歸還');await loadPage();}catch(e){error(e.message);button.disabled=false;}
});
function showLogin(){authEpoch++;role='employee';devBusy=false;devDraft=null;devFileVersion++;requestVersion++;availabilityVersion++;employeeId=null;csrfToken=null;context=null;selectedVehicle=null;historyType='maintenance';$('#workspace').hidden=true;$('#login-screen').hidden=false;$('#boot-status').hidden=true;$('#page-content').innerHTML='';if($('#edit-dialog').open)$('#edit-dialog').close();$('#login-password').value='';}
function showWorkspace(session){authEpoch=(typeof authEpoch==='number'?authEpoch:0)+1;$('#logout-button').disabled=false;$('#close-dialog').disabled=false;$('#cancel-dialog').disabled=false;role=session.role==='dev'?'dev':'employee';employeeId=role==='dev'?'DEV':session.employee.employee_id;csrfToken=session.csrf_token;$('#signed-in-name').textContent=role==='dev'?'DEV 管理員':'員工編號 '+session.employee.employee_id;$('#login-screen').hidden=true;$('#workspace').hidden=false;$('#boot-status').hidden=true;}
$('#login-form').addEventListener('submit',async event=>{event.preventDefault();const button=$('#login-button');button.disabled=true;$('#login-error').textContent='';try{const identity=$('#login-employee').value.trim().toUpperCase();const session=await api(identity==='DEV'?'/api/dev/login':'/api/auth/login','POST',{[identity==='DEV'?'username':'employee_id']:identity,password:$('#login-password').value});$('#login-password').value='';showWorkspace(session);await loadPage();}catch(e){$('#login-error').textContent=e.message;}finally{button.disabled=false;}});
$('#logout-button').addEventListener('click',async()=>{try{if(devBusy)return;await api(role==='dev'?'/api/dev/logout':'/api/auth/logout','POST');showLogin();$('#login-employee').focus();}catch(e){error(e.message);}});
window.addEventListener('hashchange',()=>{if(employeeId)loadPage();});
window.addEventListener('pageshow',event=>{if(event.persisted)initialize();});
async function initialize(){
  try{let session;try{session=await api('/api/dev/session');}catch{session=await api('/api/auth/session');}showWorkspace(session);await loadPage();}catch(e){showLogin();if(e.message!=='請先登入。'&&!e.message.includes('登入已失效'))$('#login-error').textContent=e.message;}
}
async function loadDevPage(){
 if(devBusy)return;const version=++requestVersion,epoch=authEpoch;devFileVersion++;devDraft=null;
 current='dev';$('#add-button').hidden=true;$('#nav').innerHTML=`<a href="#dev" class="nav-item active" aria-current="page">${icon('vehicles')}車隊管理</a>`;$('#page-title').textContent='車隊管理';$('#employee-name').textContent='DEV 管理員';$('#employee-department').textContent='車輛與紀錄管理';$('#employee-avatar').textContent='D';$('#signed-in-name').textContent='DEV 管理員';$('#error-banner').hidden=true;
 if($('#edit-dialog').open)$('#edit-dialog').close();$('#page-content').innerHTML='<div class="loading">正在載入車隊資料…</div>';
 try{const result=await api('/api/dev/context');if(epoch!==authEpoch||version!==requestVersion||role!=='dev')return;context=result;renderDev();}catch(e){if(epoch===authEpoch&&version===requestVersion)error(e.message);}
}
function renderDev(){
 if(!context.vehicles.some(v=>String(v.vehicle_id)===selectedVehicle))selectedVehicle=context.vehicles.length?String(context.vehicles[0].vehicle_id):null;
 $('#page-content').innerHTML=`<div class="dev-actions"><button class="primary" type="button" data-dev-create="vehicle">新增車輛</button></div><p class="field-hint">刪除採可復原封存，保留全部行程、保養與加油紀錄；已封存車輛可透過「編輯」改回可用。包含停用車輛。</p><section class="panel"><div class="table-scroll"><table aria-label="車隊管理"><thead><tr><th>編號</th><th>車牌</th><th>車型</th><th>狀態</th><th>操作</th></tr></thead><tbody>${context.vehicles.map(v=>`<tr><td>${esc(v.vehicle_id)}</td><td><button type="button" class="secondary" data-dev-select="${esc(v.vehicle_id)}" aria-pressed="${String(v.vehicle_id)===selectedVehicle}">${esc(v.license_plate)}</button></td><td>${esc(v.vehicle_model)}</td><td>${badge(v.vehicle_status)}</td><td><button type="button" class="secondary" data-dev-edit="${esc(v.vehicle_id)}">編輯</button> <button type="button" class="secondary" data-dev-archive="${esc(v.vehicle_id)}" ${v.vehicle_status==='retired'?'disabled':''}>${v.vehicle_status==='retired'?'已封存':'刪除（封存）'}</button></td></tr>`).join('')||'<tr><td colspan="5">目前沒有車輛</td></tr>'}</tbody></table></div></section><div class="dev-actions"><button class="primary" type="button" data-dev-new="maintenance" ${selectedVehicle?'':'disabled'}>新增保養紀錄</button><button class="secondary" type="button" data-dev-new="refueling" ${selectedVehicle?'':'disabled'}>新增加油紀錄</button></div><div id="dev-history">${vehicleHistory()}</div><section class="panel dev-import" aria-labelledby="dev-import-title"><h2 id="dev-import-title">CSV 批次匯入</h2><p class="field-hint">UTF-8 CSV，最多 100 筆、32 KB。vehicle_id 請填上方車輛編號。預覽後再確認匯入；任一筆有誤時整批不會寫入。</p><div class="dev-actions"><label for="dev-import-type">紀錄類型<select id="dev-import-type"><option value="maintenance">保養紀錄</option><option value="refueling">加油紀錄</option></select></label><button class="secondary" type="button" id="dev-template">下載範本</button><label for="dev-file">選擇 CSV<input id="dev-file" type="file" accept=".csv,text/csv"></label></div><p id="dev-import-error" class="form-error" role="alert"></p><div id="dev-preview"></div><button id="dev-import-submit" class="primary" type="button" disabled>確認匯入</button></section>`;
 $('#dev-import-type').addEventListener('change',()=>{devFileVersion++;devDraft=null;$('#dev-file').value='';$('#dev-preview').innerHTML='';$('#dev-import-error').textContent='';$('#dev-import-submit').disabled=true;});
 $('#dev-file').addEventListener('change',previewDevCSV);$('#dev-template').addEventListener('click',downloadDevTemplate);$('#dev-import-submit').addEventListener('click',importDevCSV);
}
function devInput(name,label,type='text',value='',attrs=''){return `<label for="dev-${name}">${label}<input id="dev-${name}" name="${name}" type="${type}" value="${esc(value)}" ${attrs} required></label>`;}
function openDevForm(type,id){
 if(devBusy||role!=='dev')return;const creating=type==='vehicle-new',record=creating?{vehicle_id:null,license_plate:'',vehicle_model:'Rolls-Royce Cullinan 6.75 V12',vehicle_status:'available'}:context.vehicles.find(v=>String(v.vehicle_id)===String(id||selectedVehicle));if(!record)return;
 formMode={dev:true,type,id:record.vehicle_id,epoch:authEpoch};$('#form-error').textContent='';$('#save-button').disabled=false;$('#save-button').textContent='儲存';$('#dialog-title').textContent=creating?'新增車輛':type==='vehicle'?'編輯車輛':type==='archive'?'刪除車輛（可復原封存）':type==='maintenance'?'新增保養紀錄':'新增加油紀錄';
 if(type==='archive'){$('#save-button').textContent='確認封存';$('#form-fields').innerHTML=`<p>確定要將 <strong>${esc(record.license_plate)}</strong>（${esc(record.vehicle_model)}）從可借用車隊移除嗎？</p><p class="field-hint">車輛與所有行程、保養、加油紀錄都會保留，之後可透過「編輯」將狀態改回「目前可借」。若有未開始或尚未歸還的預約，系統會拒絕封存。</p>`;$('#edit-dialog').showModal();return;}
 $('#form-fields').innerHTML=(type==='vehicle'||creating)?`${devInput('license_plate','車牌','text',record.license_plate,'maxlength="20"')}${devInput('vehicle_model','車型','text',record.vehicle_model,'maxlength="100"')}<label for="dev-vehicle_status">狀態<select id="dev-vehicle_status" name="vehicle_status">${['available','maintenance','retired'].map(s=>`<option value="${s}" ${s===record.vehicle_status?'selected':''}>${statusNames[s]}</option>`).join('')}</select></label>`:`<label for="dev-vehicle_id">車輛<select id="dev-vehicle_id" name="vehicle_id" required>${context.vehicles.map(v=>`<option value="${esc(v.vehicle_id)}" ${v.vehicle_id===record.vehicle_id?'selected':''}>${esc(v.license_plate)}（#${esc(v.vehicle_id)}）</option>`).join('')}</select></label>${devInput(type==='maintenance'?'maintenance_date':'refueling_date','日期','date',localTime(new Date()).slice(0,10))}${type==='maintenance'?devInput('maintenance_item','保養項目','text','','maxlength="250"'):devInput('fuel_liters','加油公升數','number','','min="0.001" max="999999.999" step="0.001"')}${devInput(type==='maintenance'?'maintenance_cost':'fuel_cost','金額（元）','number','','min="0" max="9999999999.99" step="0.01"')}`;
 $('#edit-dialog').showModal();
}
function setDevBusy(value){devBusy=value;$('#logout-button').disabled=value;$('#save-button').disabled=value;$('#close-dialog').disabled=value;$('#cancel-dialog').disabled=value;document.querySelectorAll('#page-content button,#page-content input,#page-content select,#form-fields input,#form-fields select').forEach(el=>el.disabled=value);if(!value){if($('#dev-import-submit'))$('#dev-import-submit').disabled=!devDraft;document.querySelectorAll('[data-dev-archive]').forEach(el=>el.disabled=context.vehicles.find(v=>String(v.vehicle_id)===el.dataset.devArchive)?.vehicle_status==='retired');document.querySelectorAll('[data-dev-new]').forEach(el=>el.disabled=!selectedVehicle);}}
async function saveDevForm(form){
 if(devBusy||!formMode?.dev||formMode.epoch!==authEpoch)return;const mode={...formMode},epoch=authEpoch;$('#form-error').textContent='';
 try{const values=Object.fromEntries(new FormData(form)),isVehicle=['vehicle','vehicle-new'].includes(mode.type),archiving=mode.type==='archive';let body;
 if(isVehicle){body=Object.fromEntries(Object.entries(values).map(([k,v])=>[k,v.trim()]));if(!body.license_plate||!body.vehicle_model)throw Error('車牌與車型不可空白。');}else if(!archiving)body=FleetDev.validateRecord(mode.type,values,context.vehicles);
 const path=mode.type==='vehicle-new'?'/api/dev/vehicles':isVehicle||archiving?`/api/dev/vehicles/${mode.id}`:`/api/dev/${mode.type}`;
 setDevBusy(true);const result=await api(path,archiving?'DELETE':mode.type==='vehicle'?'PUT':'POST',body);if(epoch!==authEpoch||role!=='dev')return;
 selectedVehicle=String(result.vehicle_id||body?.vehicle_id||mode.id);if(!isVehicle&&!archiving)historyType=mode.type;$('#edit-dialog').close();setDevBusy(false);toast(archiving?'車輛已封存，歷史紀錄已保留':mode.type==='vehicle-new'?'已新增車輛':'已儲存');await loadDevPage();
 }catch(e){if(epoch===authEpoch&&role==='dev')$('#form-error').textContent=e.message;}finally{if(epoch===authEpoch)setDevBusy(false);}
}
async function previewDevCSV(){
 const version=++devFileVersion,epoch=authEpoch,input=$('#dev-file'),file=input.files[0],type=$('#dev-import-type').value;devDraft=null;$('#dev-import-submit').disabled=true;$('#dev-preview').innerHTML='';$('#dev-import-error').textContent='';if(!file)return;
 try{if(file.size>32768)throw Error('CSV 不可超過 32 KB。');const text=await file.text();if(version!==devFileVersion||epoch!==authEpoch||!input.isConnected)return;const records=FleetDev.parseCSV(text,type,context.vehicles);devDraft={type,records};$('#dev-preview').innerHTML=`<p>預覽：${records.length} 筆，尚未寫入。</p><div class="table-scroll"><table aria-label="CSV 匯入預覽"><thead><tr>${FleetDev.headers[type].map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${records.map(r=>`<tr>${FleetDev.headers[type].map(h=>`<td>${esc(r[h])}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;$('#dev-import-submit').disabled=false;}catch(e){if(version===devFileVersion&&epoch===authEpoch&&input.isConnected)$('#dev-import-error').textContent=e.message;}
}
function downloadDevTemplate(){const type=$('#dev-import-type').value,id=selectedVehicle||context.vehicles[0]?.vehicle_id||1;const row=type==='maintenance'?[id,localTime(new Date()).slice(0,10),'定期保養',1000]:[id,localTime(new Date()).slice(0,10),30,900];const url=URL.createObjectURL(new Blob(['\uFEFF'+FleetDev.headers[type].join(',')+'\r\n'+row.join(',')+'\r\n'],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=`${type}-template.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function importDevCSV(){if(devBusy||!devDraft)return;const epoch=authEpoch,payload=devDraft;setDevBusy(true);$('#dev-import-error').textContent='';try{const result=await api('/api/dev/import','POST',payload);if(epoch!==authEpoch||role!=='dev')return;devDraft=null;setDevBusy(false);historyType=payload.type;toast(`已匯入 ${result.created} 筆紀錄`);await loadDevPage();}catch(e){if(epoch===authEpoch&&$('#dev-import-error')){$('#dev-import-error').textContent=e.message;}}finally{if(epoch===authEpoch)setDevBusy(false);}}
$('#page-content').addEventListener('click',event=>{if(role!=='dev'||devBusy)return;const b=event.target.closest('button');if(!b)return;if(b.dataset.devCreate)openDevForm('vehicle-new');else if(b.dataset.devArchive)openDevForm('archive',b.dataset.devArchive);else if(b.dataset.devEdit)openDevForm('vehicle',b.dataset.devEdit);else if(b.dataset.devNew)openDevForm(b.dataset.devNew);else if(b.dataset.devSelect){selectedVehicle=b.dataset.devSelect;$('#dev-history').innerHTML=vehicleHistory();document.querySelectorAll('[data-dev-select]').forEach(el=>el.setAttribute('aria-pressed',String(el.dataset.devSelect===selectedVehicle)));}else if(b.dataset.history){historyType=b.dataset.history;$('#dev-history').innerHTML=vehicleHistory();$(`[data-history="${historyType}"]`).focus();}});
$('#edit-dialog').addEventListener('cancel',event=>{if(role==='dev'&&devBusy)event.preventDefault();});
initialize();
